import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.Di-jvWLj.js";const m=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/index.md","filePath":"deployment/index.md","lastUpdated":1793872669000}'),r={name:"deployment/index.md"};function i(s,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><p>The workflow: agents live in their own GitHub repository, CI builds a Docker image, and Flux deploys it to your Kubernetes cluster. Every agent repository is an app with one or more agents, its own store connection, its own GitHub App and its own channels.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span>agent repo --push--&gt; CI --image--&gt; registry --Flux image automation--&gt; HelmRelease --&gt; cluster</span></span>
<span class="line"><span>                                                                            |</span></span>
<span class="line"><span>                                         OpenClaw --MCP--&gt; app (/mcp) --hooks--&gt; OpenClaw</span></span>
<span class="line"><span>                                         GitHub ---webhooks---&gt; app (/channels/github) --comments--&gt; GitHub</span></span></code></pre></div><h2 id="pieces" tabindex="-1">Pieces <a class="header-anchor" href="#pieces" aria-label="Permalink to &quot;Pieces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Built as</th></tr></thead><tbody><tr><td><a href="/reference/app"><code>@chamvi/app</code></a> + <a href="/reference/cli"><code>@chamvi/cli</code></a></td><td><code>createApp({ agents, modules })</code> boots config, store, engine (with its channels) and HTTP in order and tears them down in reverse, draining on <code>SIGTERM</code>. The <code>chamvi</code> bin with <code>dev</code>, <code>build</code>, <code>start</code>, <code>run-job</code> and <code>migrate</code>. See <a href="/guide/app">Apps &amp; Modules</a></td></tr><tr><td><a href="/deployment/docker">Base image</a></td><td><code>ghcr.io/chamvi/node</code>: Node 26 on Debian trixie slim, tini, uid 1000, <code>linux/amd64</code> and <code>linux/arm64</code>; agent repositories use a two-stage Dockerfile</td></tr><tr><td><a href="/deployment/kubernetes">Helm chart</a></td><td><a href="https://github.com/chamvi/helm" target="_blank" rel="noreferrer">chamvi/helm</a>: one shared OCI chart, <code>oci://ghcr.io/chamvi/helm/agent-app</code>, for every agent app; each repository gets a small <code>HelmRelease</code></td></tr><tr><td>Template repository</td><td><a href="https://github.com/chamvi/agent-template" target="_blank" rel="noreferrer">chamvi/agent-template</a>: a GitHub template with an example agent, Dockerfile, CI that builds and tags images for Flux, and example Flux manifests</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Configuration comes from <a href="/reference/app#environment">environment variables</a>, typically from Kubernetes Secrets: the database URL, the HTTP port, the default model and provider API keys (<code>CHAMVI_MODEL</code>, <code>CHAMVI_PROVIDER_&lt;NAME&gt;_*</code> or the bare <code>ANTHROPIC_API_KEY</code>, ...; only providers you declare, no gateway by default, see <a href="/guide/models">Pick a Model</a>; <code>chamvi start --check</code> checks them, the store and the agent folders in CI with the production or staging env), static API tokens for machine clients, and OpenClaw and GitHub settings. How the Secrets get into the cluster (plain Secrets, SOPS, External Secrets) is the cluster&#39;s choice.</p><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p>The app writes structured JSON log lines to stderr, and the HTTP app serves Prometheus metrics on <code>/metrics</code> (the chart&#39;s optional ServiceMonitor scrapes them). OpenTelemetry spans for runs and steps are planned.</p><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><ul><li><a href="/deployment/docker">Docker Image</a></li><li><a href="/deployment/kubernetes">Kubernetes &amp; Flux</a></li><li><a href="/deployment/replicas">Multiple Replicas</a></li><li><a href="/deployment/openclaw">OpenClaw</a></li><li><a href="/deployment/whatsapp">WhatsApp</a></li><li><a href="/deployment/discord">Discord</a></li><li><a href="/deployment/github-app">GitHub App</a></li></ul>`,11)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
